('2fe43d0e-0e55-55cf-94d3-e420f173b7e7', '2fb8b926-5747-545d-9af6-82cb4940584c', 'mcq', 'situation', 'bn', 'বাগানের মোট ক্ষেত্রফল কত বর্গমিটার?', '{"options":["$x^2 + 4$","$x^2 + 4x + 4$","$x^2 + 2x + 4$","$4x + 4$"],"context":"একটি বর্গাকার বাগানের প্রতিটি বাহুর দৈর্ঘ্য $(x + 2)$ মিটার। বাগানের ঠিক মাঝখানে $(x - 2)$ মিটার বাহুবিশিষ্ট একটি বর্গাকার পুকুর কাটা হলো।"}'::jsonb, '{"index":1}'::jsonb, '$(x + 2)^2 = x^2 + 4x + 4$।', null, 'original', null, null, 2, array['square-sum','area']::text[], true),
('dd61f9a8-e6d3-5a26-8879-77c8ea2de9ea', '2fb8b926-5747-545d-9af6-82cb4940584c', 'mcq', 'situation', 'bn', 'পুকুর বাদে বাগানের বাকি অংশের ক্ষেত্রফল কত?', '{"options":["$4x$","$8$","$8x$","$2x^2 + 8$"],"context":"একটি বর্গাকার বাগানের প্রতিটি বাহুর দৈর্ঘ্য $(x + 2)$ মিটার। বাগানের ঠিক মাঝখানে $(x - 2)$ মিটার বাহুবিশিষ্ট একটি বর্গাকার পুকুর কাটা হলো।"}'::jsonb, '{"index":2}'::jsonb, '$(x + 2)^2 - (x - 2)^2 = 4 \cdot x \cdot 2 = 8x$ (সূত্র: $(a+b)^2 - (a-b)^2 = 4ab$)।', null, 'original', null, null, 3, array['identities','area']::text[], true),
('5a33f802-8ff2-510c-818a-c90b50a8c8e1', '2fb8b926-5747-545d-9af6-82cb4940584c', 'mcq', 'situation', 'bn', '$x = 10$ হলে পুকুরের ক্ষেত্রফল কত বর্গমিটার?', '{"options":["$144$","$80$","$100$","$64$"],"context":"একটি বর্গাকার বাগানের প্রতিটি বাহুর দৈর্ঘ্য $(x + 2)$ মিটার। বাগানের ঠিক মাঝখানে $(x - 2)$ মিটার বাহুবিশিষ্ট একটি বর্গাকার পুকুর কাটা হলো।"}'::jsonb, '{"index":3}'::jsonb, 'পুকুরের বাহু $10 - 2 = 8$ মিটার, ক্ষেত্রফল $8^2 = 64$।', null, 'original', null, null, 2, array['evaluate','area']::text[], true),
('bfa8db1c-3e80-575e-baa2-1f4a01f4fc46', '2fb8b926-5747-545d-9af6-82cb4940584c', 'cq', 'cq', 'bn', '$x + \frac{1}{x} = 3$', null, '[{"part":"a","model":"$x^2 + \\frac{1}{x^2} = (x + \\frac{1}{x})^2 - 2 = 3^2 - 2 = 7$","rubric":[{"points":1,"criterion":"সঠিক সূত্র ব্যবহার করে মান $7$ পেয়েছে"}]},{"part":"b","model":"$(x - \\frac{1}{x})^2 = (x + \\frac{1}{x})^2 - 4 \\cdot x \\cdot \\frac{1}{x}$\n\n$= 3^2 - 4 = 9 - 4 = 5$ (দেখানো হলো)","rubric":[{"points":1,"criterion":"$(a - b)^2 = (a + b)^2 - 4ab$ সম্পর্কটি লিখেছে"},{"points":1,"criterion":"মান বসিয়ে $5$ দেখিয়েছে"}]},{"part":"c","model":"$a^3 + b^3 = (a + b)^3 - 3ab(a + b)$ সূত্রে $a = x$, $b = \\frac{1}{x}$, $ab = 1$:\n\n$x^3 + \\frac{1}{x^3} = (x + \\frac{1}{x})^3 - 3(x + \\frac{1}{x})$\n\n$= 27 - 9 = 18$","rubric":[{"points":1,"criterion":"ঘনের সঠিক সূত্র লিখেছে"},{"points":1,"criterion":"$ab = 1$ ধরে সঠিকভাবে মান বসিয়েছে"},{"points":1,"criterion":"সঠিক উত্তর $18$"}]},{"part":"d","model":"$(x^2 + \\frac{1}{x^2})(x^3 + \\frac{1}{x^3}) = x^5 + \\frac{1}{x} + x + \\frac{1}{x^5}$\n\nতাই $x^5 + \\frac{1}{x^5} = (x^2 + \\frac{1}{x^2})(x^3 + \\frac{1}{x^3}) - (x + \\frac{1}{x})$\n\n(ক) ও (গ) থেকে: $= 7 \\times 18 - 3 = 126 - 3 = 123$ (প্রমাণিত)","rubric":[{"points":1,"criterion":"বর্গ ও ঘনের রাশি গুণ করার কৌশল বেছে নিয়েছে"},{"points":1,"criterion":"গুণফল সঠিকভাবে বিস্তৃত করেছে"},{"points":1,"criterion":"$x + \\frac{1}{x}$ বিয়োগ করে সম্পর্ক সাজিয়েছে"},{"points":1,"criterion":"আগের ফল ব্যবহার করে $123$ প্রমাণ করেছে"}]}]'::jsonb, null, '[{"part":"a","marks":1,"prompt":"$x^2 + \\frac{1}{x^2}$ এর মান নির্ণয় করো।"},{"part":"b","marks":2,"prompt":"দেখাও যে, $(x - \\frac{1}{x})^2 = 5$।"},{"part":"c","marks":3,"prompt":"$x^3 + \\frac{1}{x^3}$ এর মান নির্ণয় করো।"},{"part":"d","marks":4,"prompt":"প্রমাণ করো যে, $x^5 + \\frac{1}{x^5} = 123$।"}]'::jsonb, 'original', null, null, 3, array['reciprocal']::text[], true),
('038b4937-7431-5099-b5bb-397a58610249', '2fb8b926-5747-545d-9af6-82cb4940584c', 'cq', 'cq', 'bn', '$A = x^2 + 5x + 6$, $B = x^2 - 4$, $C = x^3 + 8$', null, '[{"part":"a","model":"$B = x^2 - 2^2 = (x + 2)(x - 2)$","rubric":[{"points":1,"criterion":"সঠিক উৎপাদক"}]},{"part":"b","model":"গুণফল $6$, যোগফল $5$: সংখ্যা দুটি $2$ ও $3$।\n\n$A = x^2 + 2x + 3x + 6 = x(x + 2) + 3(x + 2) = (x + 2)(x + 3)$","rubric":[{"points":1,"criterion":"মধ্যপদ $2x + 3x$ এ ভেঙেছে"},{"points":1,"criterion":"সাধারণ উৎপাদক বের করে সঠিক উত্তর"}]},{"part":"c","model":"$C = x^3 + 2^3 = (x + 2)(x^2 - 2x + 4)$\n\n$A = (x + 2)(x + 3)$, $B = (x + 2)(x - 2)$\n\nতিনটিতেই আছে $(x + 2)$, তাই সাধারণ উৎপাদক $x + 2$।","rubric":[{"points":1,"criterion":"$a^3 + b^3$ সূত্র ব্যবহার"},{"points":1,"criterion":"$C$ এর সঠিক উৎপাদক"},{"points":1,"criterion":"সাধারণ উৎপাদক $x + 2$"}]},{"part":"d","model":"$A - B = (x^2 + 5x + 6) - (x^2 - 4) = 5x + 10 = 5(x + 2)$\n\n$\\frac{A - B}{C} = \\frac{5(x + 2)}{(x + 2)(x^2 - 2x + 4)} = \\frac{5}{x^2 - 2x + 4}$ (যখন $x \\ne -2$)\n\nহর: $x^2 - 2x + 4 = (x - 1)^2 + 3 \\ge 3$, কারণ কোনো বর্গ ঋণাত্মক নয়।\n\nহর সবচেয়ে ছোট হলে ভগ্নাংশ সবচেয়ে বড়। $x = 1$ হলে হর $3$, তাই সর্বোচ্চ মান $\\frac{5}{3}$।","rubric":[{"points":1,"criterion":"$A - B = 5(x + 2)$"},{"points":1,"criterion":"সাধারণ উৎপাদক কেটে $\\frac{5}{x^2 - 2x + 4}$"},{"points":1,"criterion":"হরকে $(x - 1)^2 + 3$ আকারে লিখেছে"},{"points":1,"criterion":"যুক্তিসহ সর্বোচ্চ মান $\\frac{5}{3}$"}]}]'::jsonb, null, '[{"part":"a","marks":1,"prompt":"$B$ কে উৎপাদকে বিশ্লেষণ করো।"},{"part":"b","marks":2,"prompt":"মধ্যপদ বিভক্তিকরণের মাধ্যমে $A$ কে উৎপাদকে বিশ্লেষণ করো।"},{"part":"c","marks":3,"prompt":"$C$ কে উৎপাদকে বিশ্লেষণ করো এবং $A$, $B$, $C$ এর সাধারণ উৎপাদক নির্ণয় করো।"},{"part":"d","marks":4,"prompt":"$\\frac{A - B}{C}$ কে লঘিষ্ঠ আকারে প্রকাশ করো এবং দেখাও যে বাস্তব $x$ এর জন্য এর সর্বোচ্চ মান $\\frac{5}{3}$।"}]'::jsonb, 'original', null, null, 4, array['factorise','middle-term','cube-sum']::text[], true),
('da79bd6a-061e-5076-a2fc-e5dd699737d7', '2fb8b926-5747-545d-9af6-82cb4940584c', 'cq', 'cq', 'bn', 'একটি আয়তাকার জমির দৈর্ঘ্য $(2x + 3)$ মিটার ও প্রস্থ $(2x - 3)$ মিটার। পাশের একটি বর্গাকার জমির প্রতিটি বাহু $(2x + 1)$ মিটার।', null, '[{"part":"a","model":"$(2x + 3)(2x - 3) = (2x)^2 - 3^2 = 4x^2 - 9$ বর্গমিটার","rubric":[{"points":1,"criterion":"$4x^2 - 9$"}]},{"part":"b","model":"বর্গাকার জমি: $(2x + 1)^2 = 4x^2 + 4x + 1$\n\nপার্থক্য: $(4x^2 + 4x + 1) - (4x^2 - 9) = 4x + 10$\n\nজমির মাপ ধনাত্মক হতে হলে $x > 1.5$, তাই $4x + 10 > 0$। বর্গাকার জমিটি $(4x + 10)$ বর্গমিটার বড়।","rubric":[{"points":1,"criterion":"বর্গের ক্ষেত্রফল সঠিক"},{"points":1,"criterion":"পার্থক্য $4x + 10$ ও কোনটি বড় তা বলেছে"}]},{"part":"c","model":"পরিসীমা $= 2\\{(2x + 3) + (2x - 3)\\} = 2 \\times 4x = 8x$\n\n$8x = 40$, তাই $x = 5$\n\nআয়তাকার: $13 \\times 7 = 91$ বর্গমিটার; বর্গাকার: $11^2 = 121$ বর্গমিটার","rubric":[{"points":1,"criterion":"পরিসীমা $8x$ লিখে $x = 5$"},{"points":1,"criterion":"আয়তের ক্ষেত্রফল $91$"},{"points":1,"criterion":"বর্গের ক্ষেত্রফল $121$"}]},{"part":"d","model":"বাইরের বাহু $11$ মিটার। দুই পাশে $1$ মিটার করে রাস্তা, তাই ভেতরের বাহু $11 - 2 = 9$ মিটার।\n\nরাস্তার ক্ষেত্রফল $= 11^2 - 9^2 = (11 + 9)(11 - 9) = 20 \\times 2 = 40$ বর্গমিটার\n\nখরচ $= 40 \\times 50 = 2000$ টাকা","rubric":[{"points":1,"criterion":"ভেতরের বাহু $9$ মিটার (দুই পাশ বাদ)"},{"points":1,"criterion":"$a^2 - b^2 = (a + b)(a - b)$ প্রয়োগ"},{"points":1,"criterion":"রাস্তার ক্ষেত্রফল $40$"},{"points":1,"criterion":"খরচ $2000$ টাকা"}]}]'::jsonb, null, '[{"part":"a","marks":1,"prompt":"আয়তাকার জমির ক্ষেত্রফল $x$ এর মাধ্যমে প্রকাশ করো।"},{"part":"b","marks":2,"prompt":"কোন জমিটি বড় এবং কত বর্গমিটার বড়?"},{"part":"c","marks":3,"prompt":"আয়তাকার জমির পরিসীমা $40$ মিটার হলে $x$ এর মান এবং দুটি জমির ক্ষেত্রফল নির্ণয় করো।"},{"part":"d","marks":4,"prompt":"(গ) এর মান ধরে বর্গাকার জমির ভেতরে চারদিকে $1$ মিটার চওড়া একটি রাস্তা আছে। $a^2 - b^2$ সূত্র ব্যবহার করে রাস্তার ক্ষেত্রফল নির্ণয় করো এবং প্রতি বর্গমিটার $50$ টাকা হিসেবে রাস্তা বাঁধাতে কত খরচ হবে বের করো।"}]'::jsonb, 'original', null, null, 3, array['difference-of-squares','area','real-life']::text[], true),
('0c162c88-994a-548b-b341-0fb2371a38c8', '2fb8b926-5747-545d-9af6-82cb4940584c', 'cq', 'cq', 'bn', '$a + b = 6$ এবং $ab = 8$', null, '[{"part":"a","model":"$a^2 + b^2 = (a + b)^2 - 2ab = 36 - 16 = 20$","rubric":[{"points":1,"criterion":"সঠিক মান $20$"}]},{"part":"b","model":"$(a - b)^2 = (a + b)^2 - 4ab = 36 - 32 = 4$","rubric":[{"points":1,"criterion":"সম্পর্ক $(a - b)^2 = (a + b)^2 - 4ab$"},{"points":1,"criterion":"সঠিক মান $4$"}]},{"part":"c","model":"$a^3 + b^3 = (a + b)^3 - 3ab(a + b) = 216 - 3 \\times 8 \\times 6 = 216 - 144 = 72$","rubric":[{"points":1,"criterion":"সঠিক সূত্র"},{"points":1,"criterion":"মান বসানো"},{"points":1,"criterion":"সঠিক উত্তর $72$"}]},{"part":"d","model":"$a^4 + a^2b^2 + b^4 = (a^2 + b^2)^2 - a^2b^2 = (a^2 + b^2 + ab)(a^2 + b^2 - ab)$\n\n(ক) থেকে $a^2 + b^2 = 20$, আর $ab = 8$:\n\n$= (20 + 8)(20 - 8) = 28 \\times 12 = 336$ (দেখানো হলো)","rubric":[{"points":1,"criterion":"$(a^2 + b^2)^2 - a^2b^2$ আকারে লিখেছে"},{"points":1,"criterion":"বর্গের অন্তর হিসেবে উৎপাদক"},{"points":1,"criterion":"আগের মান বসিয়েছে"},{"points":1,"criterion":"সঠিক ফল $336$"}]}]'::jsonb, null, '[{"part":"a","marks":1,"prompt":"$a^2 + b^2$ এর মান নির্ণয় করো।"},{"part":"b","marks":2,"prompt":"$(a - b)^2$ এর মান নির্ণয় করো।"},{"part":"c","marks":3,"prompt":"$a^3 + b^3$ এর মান নির্ণয় করো।"},{"part":"d","marks":4,"prompt":"উৎপাদকে বিশ্লেষণ ব্যবহার করে দেখাও যে, $a^4 + a^2b^2 + b^4 = 336$।"}]'::jsonb, 'original', null, null, 3, array['sum-product','cube-sum']::text[], true),
('c46a1240-1024-53f5-84d5-a1b66bc28593', '2fb8b926-5747-545d-9af6-82cb4940584c', 'mcq', 'single', 'en', 'What is the expanded form of $(x + 5)^2$?', '{"options":["$x^2 + 10x + 25$","$x^2 + 25$","$x^2 + 5x + 25$","$x^2 + 10x + 10$"]}'::jsonb, '{"index":0}'::jsonb, '$a = x$, $b = 5$: $x^2 + 2 \cdot 5x + 25 = x^2 + 10x + 25$.', null, 'original', null, null, 1, array['square-sum']::text[], true),
('1bf0f1a6-fb1d-59ad-ba02-93dd946c75c1', '2fb8b926-5747-545d-9af6-82cb4940584c', 'mcq', 'single', 'en', '$(2a - 3)^2 = ?$', '{"options":["$4a^2 - 9$","$4a^2 - 6a + 9$","$4a^2 - 12a + 9$","$2a^2 - 12a + 9$"]}'::jsonb, '{"index":2}'::jsonb, '$(2a)^2 = 4a^2$, middle term $-2 \cdot 2a \cdot 3 = -12a$, last term $9$.', null, 'original', null, null, 2, array['square-difference']::text[], true),
