('1d09d7e3-5c97-5dd5-9538-cf02f26762d8', '2fb8b926-5747-545d-9af6-82cb4940584c', 'mcq', 'single', 'en', 'If $x + \frac{1}{x} = 4$, what is $x^2 + \frac{1}{x^2}$?', '{"options":["$16$","$14$","$18$","$12$"]}'::jsonb, '{"index":1}'::jsonb, '$x^2 + \frac{1}{x^2} = (x + \frac{1}{x})^2 - 2 \cdot x \cdot \frac{1}{x} = 16 - 2 = 14$.', null, 'original', null, null, 3, array['reciprocal']::text[], true),
