('3cf475f2-91ae-54ea-b85d-6acb5e7c48d6', '2fb8b926-5747-545d-9af6-82cb4940584c', 'mcq', 'single', 'en', '$(a + b + c)^2 = ?$', '{"options":["$a^2 + b^2 + c^2$","$a^2 + b^2 + c^2 + ab + bc + ca$","$a^2 + b^2 + c^2 + 2ab + 2bc + 2ca$","$a^2 + b^2 + c^2 + 2abc$"]}'::jsonb, '{"index":2}'::jsonb, '$(a + b + c)^2 = a^2 + b^2 + c^2 + 2(ab + bc + ca)$. Each pair product appears twice.', null, 'original', null, null, 2, array['square-three-terms']::text[], true),
('f82d5c9b-3efd-5cf0-808e-d426bd657be4', '2fb8b926-5747-545d-9af6-82cb4940584c', 'mcq', 'single', 'en', 'If $x = 2$ and $y = -1$, what is $x^2 + 2xy + y^2$?', '{"options":["$9$","$5$","$1$","$3$"]}'::jsonb, '{"index":2}'::jsonb, 'The expression is $(x + y)^2 = (2 - 1)^2 = 1$.', null, 'original', null, null, 2, array['square-sum','evaluate']::text[], true),
