('ac61f57c-0079-5940-98d8-87194210f5c8', '111e790d-4f54-5781-82bc-2c877c0315b2', 'mcq', 'situation', 'bn', 'মোট $100\,\text{s}$-এ ট্রেনটি কত দূরত্ব অতিক্রম করল?', '{"options":["$400\\,\\text{m}$","$1200\\,\\text{m}$","$1600\\,\\text{m}$","$2000\\,\\text{m}$"],"context":"একটি ট্রেন স্টেশন থেকে স্থির অবস্থা থেকে ছেড়ে $0.5\\,\\text{m/s}^2$ সুষম ত্বরণে $40\\,\\text{s}$ চলল। এরপর পরবর্তী $60\\,\\text{s}$ ট্রেনটি সুষম বেগে চলল।"}'::jsonb, '{"index":2}'::jsonb, 'প্রথম অংশ: $\frac{1}{2} \times 0.5 \times 40^2 = 400\,\text{m}$। দ্বিতীয় অংশ: $20 \times 60 = 1200\,\text{m}$। মোট $1600\,\text{m}$।', null, 'original', null, null, 4, array['equations']::text[], true),
('b895a012-d1fb-5d2f-b44b-0d2875c0c86f', '111e790d-4f54-5781-82bc-2c877c0315b2', 'cq', 'cq', 'bn', 'রাফি $72\,\text{km/h}$ বেগে মোটরসাইকেল চালাচ্ছিল। হঠাৎ সে $50\,\text{m}$ সামনে রাস্তায় একটি গরু দেখল এবং সাথে সাথে ব্রেক কষল। মোটরসাইকেলটি $-5\,\text{m/s}^2$ সুষম ত্বরণে থামতে লাগল।', null, '[{"part":"a","model":"সময়ের সাথে বস্তুর বেগ কমতে থাকলে বেগ হ্রাসের হারকে মন্দন বলে। এটি ঋণাত্মক ত্বরণ।","rubric":[{"points":1,"criterion":"বেগ হ্রাসের হার বা ঋণাত্মক ত্বরণ হিসেবে সঠিক সংজ্ঞা"}]},{"part":"b","model":"ত্বরণ হলো বেগ পরিবর্তনের হার, $a = \\frac{v - u}{t}$। সুষম বেগে বেগের মান ও দিক বদলায় না, তাই $v = u$।\n\nফলে $a = \\frac{u - u}{t} = 0$।","rubric":[{"points":1,"criterion":"ত্বরণকে বেগ পরিবর্তনের হার হিসেবে উল্লেখ করেছে"},{"points":1,"criterion":"বেগ অপরিবর্তিত থাকায় $a = 0$ দেখিয়েছে"}]},{"part":"c","model":"$u = 72\\,\\text{km/h} = \\frac{72 \\times 1000}{3600} = 20\\,\\text{m/s}$, $v = 0$, $a = -5\\,\\text{m/s}^2$\n\n$v = u + at \\Rightarrow 0 = 20 - 5t$\n\n$t = 4\\,\\text{s}$","rubric":[{"points":1,"criterion":"$72\\,\\text{km/h}$ কে $20\\,\\text{m/s}$ এ রূপান্তর করেছে"},{"points":1,"criterion":"$v = u + at$ সঠিকভাবে বসিয়েছে"},{"points":1,"criterion":"সঠিক উত্তর $4\\,\\text{s}$"}]},{"part":"d","model":"থামার আগে অতিক্রান্ত দূরত্ব: $v^2 = u^2 + 2as$\n\n$0 = 20^2 + 2(-5)s \\Rightarrow s = \\frac{400}{10} = 40\\,\\text{m}$\n\nগরুটি $50\\,\\text{m}$ দূরে, মোটরসাইকেল থামে $40\\,\\text{m}$ এ। তাই রাফি গরু থেকে $10\\,\\text{m}$ আগে থেমে যাবে এবং ধাক্কা এড়াতে পারবে।\n\nতবে বাস্তবে চালক দেখার পর ব্রেক কষতে কিছুটা সময় লাগে (প্রতিক্রিয়া সময়)। সেই সময়ে মোটরসাইকেল $20\\,\\text{m/s}$ বেগে চলতে থাকে। প্রতিক্রিয়া সময় $0.5\\,\\text{s}$ এর বেশি হলে আরও $10\\,\\text{m}$ এর বেশি যাবে এবং ধাক্কা লাগবে।","rubric":[{"points":1,"criterion":"$v^2 = u^2 + 2as$ ব্যবহার করেছে"},{"points":1,"criterion":"থামার দূরত্ব $40\\,\\text{m}$ পেয়েছে"},{"points":1,"criterion":"$50\\,\\text{m}$ এর সাথে তুলনা করে সিদ্ধান্ত দিয়েছে"},{"points":1,"criterion":"প্রতিক্রিয়া সময় বা বাস্তব সীমাবদ্ধতা বিবেচনা করেছে"}]}]'::jsonb, null, '[{"part":"a","marks":1,"prompt":"মন্দন কাকে বলে?"},{"part":"b","marks":2,"prompt":"সুষম বেগে চলমান বস্তুর ত্বরণ শূন্য কেন? ব্যাখ্যা করো।"},{"part":"c","marks":3,"prompt":"ব্রেক কষার পর মোটরসাইকেলটি থামতে কত সময় লাগবে, নির্ণয় করো।"},{"part":"d","marks":4,"prompt":"রাফি কি গরুটিকে ধাক্কা দেওয়া এড়াতে পারবে? গাণিতিক যুক্তিসহ বিশ্লেষণ করো।"}]'::jsonb, 'original', null, null, 3, array['equations','deceleration']::text[], true),
('117b5e4d-4d10-5d0c-9082-9b97e4dcb8cd', '111e790d-4f54-5781-82bc-2c877c0315b2', 'cq', 'cq', 'bn', 'একটি ভবনের ছাদ থেকে একটি বল ছেড়ে দেওয়া হলো। বলটি $4\,\text{s}$ পরে মাটিতে পড়ল। ($g = 9.8\,\text{m/s}^2$, বাতাসের বাধা উপেক্ষণীয়)', null, '[{"part":"a","model":"পৃথিবীর আকর্ষণে মুক্তভাবে পড়ন্ত বস্তুর বেগ বৃদ্ধির হারকে অভিকর্ষজ ত্বরণ বলে। এর মান প্রায় $9.8\\,\\text{m/s}^2$।","rubric":[{"points":1,"criterion":"সঠিক সংজ্ঞা"}]},{"part":"b","model":"মুক্তভাবে পড়ন্ত বস্তুর ত্বরণ $g$ বস্তুর ভরের উপর নির্ভর করে না। বাতাসে পালক ধীরে পড়ে কারণ বাতাসের বাধা তার উপর বেশি প্রভাব ফেলে।\n\nবায়ুশূন্য স্থানে বাধা নেই, তাই দুটির ত্বরণ সমান ($g$), এবং একই উচ্চতা থেকে একই সময়ে মাটিতে পড়ে।","rubric":[{"points":1,"criterion":"$g$ ভরের উপর নির্ভর করে না বলেছে"},{"points":1,"criterion":"বাতাসের বাধার ভূমিকা ব্যাখ্যা করেছে"}]},{"part":"c","model":"$u = 0$, $t = 4\\,\\text{s}$, $g = 9.8\\,\\text{m/s}^2$\n\n$h = ut + \\frac{1}{2}gt^2 = 0 + \\frac{1}{2} \\times 9.8 \\times 16$\n\n$h = 78.4\\,\\text{m}$","rubric":[{"points":1,"criterion":"$u = 0$ শনাক্ত করেছে"},{"points":1,"criterion":"$h = \\frac{1}{2}gt^2$ ব্যবহার করেছে"},{"points":1,"criterion":"সঠিক উত্তর $78.4\\,\\text{m}$"}]},{"part":"d","model":"প্রথম $2\\,\\text{s}$ এ: $h_1 = \\frac{1}{2} \\times 9.8 \\times 2^2 = 19.6\\,\\text{m}$\n\nশেষ $2\\,\\text{s}$ এ: $78.4 - 19.6 = 58.8\\,\\text{m}$\n\n$19.6\\,\\text{m}$ হলো মোট উচ্চতার এক-চতুর্থাংশ, অর্ধেক নয়।\n\nকারণ: বল প্রতি সেকেন্ডে দ্রুততর হয়, তাই পরের সমান সময়ে বেশি পথ যায়। দূরত্ব $t^2$ এর সমানুপাতিক, তাই অর্ধেক সময়ে দূরত্ব $(\\frac{1}{2})^2 = \\frac{1}{4}$ অংশ।","rubric":[{"points":1,"criterion":"প্রথম $2\\,\\text{s}$ এর দূরত্ব $19.6\\,\\text{m}$"},{"points":1,"criterion":"মোট উচ্চতার সাথে তুলনা করেছে"},{"points":1,"criterion":"অর্ধেক নয়, এক-চতুর্থাংশ সিদ্ধান্ত দিয়েছে"},{"points":1,"criterion":"$h \\propto t^2$ দিয়ে কারণ ব্যাখ্যা করেছে"}]}]'::jsonb, null, '[{"part":"a","marks":1,"prompt":"অভিকর্ষজ ত্বরণ কাকে বলে?"},{"part":"b","marks":2,"prompt":"বায়ুশূন্য স্থানে একটি পালক ও একটি পাথর একসাথে পড়ে কেন? ব্যাখ্যা করো।"},{"part":"c","marks":3,"prompt":"ভবনটির উচ্চতা নির্ণয় করো।"},{"part":"d","marks":4,"prompt":"পতনের প্রথম $2\\,\\text{s}$ এ বলটি মোট উচ্চতার অর্ধেক পথ যায় কিনা, যাচাই করে মতামত দাও।"}]'::jsonb, 'original', null, null, 3, array['free-fall']::text[], true),
('063e4e9c-0f0e-5af9-a586-36e61194cb87', '111e790d-4f54-5781-82bc-2c877c0315b2', 'cq', 'cq', 'bn', 'একটি গাড়ির গতির বিবরণ:

- $0$ থেকে $10\,\text{s}$: বেগ সুষমভাবে $0$ থেকে $15\,\text{m/s}$ হলো
