('66b54d8f-fd72-583d-aa5c-1fb3899a1413', '1f6187ce-0423-5375-872c-f8baa84b57a1', 'cq', 'cq', 'bn', 'তানভীর বন্ধুর কাছ থেকে একটি পেনড্রাইভ এনে স্ক্যান না করেই তার কম্পিউটারে খুলল। কিছুদিন পর কম্পিউটারটি খুব ধীর হয়ে গেল এবং তার প্রজেক্টের কয়েকটি ফাইল খুলছিল না। তার বোন রিমা নিয়মিত তার ফাইলগুলো গুগল ড্রাইভে রাখে এবং অ্যান্টিভাইরাস হালনাগাদ রাখে।', null, '[{"part":"a","model":"কম্পিউটার ভাইরাস এক ধরনের ক্ষতিকর প্রোগ্রাম যা অন্য ফাইল বা প্রোগ্রামের সাথে জুড়ে নিজের কপি তৈরি করে ছড়ায় এবং ফাইল বা সিস্টেমের ক্ষতি করে।","rubric":[{"points":1,"criterion":"ক্ষতিকর প্রোগ্রাম যা অন্য ফাইলের সাথে জুড়ে ছড়ায়, উল্লেখ করেছে"}]},{"part":"b","model":"ভাইরাস ছড়াতে অন্য ফাইলের সাথে জুড়ে থাকে এবং ব্যবহারকারী ফাইলটি চালালে সক্রিয় হয়।\n\nওয়ার্মের অন্য ফাইলের দরকার হয় না; এটি নিজেই নেটওয়ার্কের মাধ্যমে এক কম্পিউটার থেকে অন্যটিতে নিজের কপি পাঠিয়ে ছড়ায়।","rubric":[{"points":1,"criterion":"ভাইরাস অন্য ফাইলের উপর নির্ভরশীল"},{"points":1,"criterion":"ওয়ার্ম নিজে নিজে নেটওয়ার্কে ছড়ায়"}]},{"part":"c","model":"কারণ: বন্ধুর পেনড্রাইভে সম্ভবত ভাইরাস ছিল। স্ক্যান না করে খোলায় ভাইরাস কম্পিউটারে ঢুকে প্রসেসর ও মেমোরি দখল করেছে (তাই ধীর) এবং ফাইল নষ্ট করেছে।\n\nপ্রতিকার: হালনাগাদ অ্যান্টিভাইরাস দিয়ে পুরো কম্পিউটার স্ক্যান করে ভাইরাস সরানো, নষ্ট ফাইল ব্যাকআপ থাকলে সেখান থেকে ফেরত আনা, আর ভবিষ্যতে পেনড্রাইভ খোলার আগে স্ক্যান করা।","rubric":[{"points":1,"criterion":"পেনড্রাইভ থেকে ভাইরাস সংক্রমণকে কারণ বলেছে"},{"points":1,"criterion":"ধীর হওয়া ও ফাইল নষ্ট হওয়ার সাথে সম্পর্ক দেখিয়েছে"},{"points":1,"criterion":"অন্তত দুটি সঠিক প্রতিকার"}]},{"part":"d","model":"রিমার ফাইল বেশি নিরাপদ।\n\nপ্রথমত, রিমা অ্যান্টিভাইরাস হালনাগাদ রাখে, তাই নতুন ভাইরাসও ধরা পড়ার সম্ভাবনা বেশি। তানভীর স্ক্যান না করেই পেনড্রাইভ খুলেছে।\n\nদ্বিতীয়ত, রিমার ফাইলের কপি গুগল ড্রাইভে (ক্লাউডে) আছে। কম্পিউটার নষ্ট বা সংক্রমিত হলেও সে ফাইল ফেরত পাবে। তানভীরের ব্যাকআপ না থাকায় নষ্ট ফাইল হারিয়ে যেতে পারে।\n\nতবে ক্লাউড অ্যাকাউন্টও শক্ত পাসওয়ার্ড ও দুই ধাপের যাচাই দিয়ে সুরক্ষিত রাখতে হবে, নইলে সেখানেও ঝুঁকি থাকে।","rubric":[{"points":1,"criterion":"রিমার ফাইল বেশি নিরাপদ, স্পষ্ট সিদ্ধান্ত"},{"points":1,"criterion":"হালনাগাদ অ্যান্টিভাইরাসের ভূমিকা"},{"points":1,"criterion":"ক্লাউড ব্যাকআপের ভূমিকা"},{"points":1,"criterion":"সীমাবদ্ধতা বা অতিরিক্ত সতর্কতা (পাসওয়ার্ড/2FA) বিবেচনা"}]}]'::jsonb, null, '[{"part":"a","marks":1,"prompt":"কম্পিউটার ভাইরাস কী?"},{"part":"b","marks":2,"prompt":"ভাইরাস ও ওয়ার্মের মধ্যে পার্থক্য ব্যাখ্যা করো।"},{"part":"c","marks":3,"prompt":"তানভীরের কম্পিউটারের সমস্যার কারণ ও প্রতিকার ব্যাখ্যা করো।"},{"part":"d","marks":4,"prompt":"তানভীর ও রিমার মধ্যে কার ফাইল বেশি নিরাপদ? যুক্তিসহ মূল্যায়ন করো।"}]'::jsonb, 'original', null, null, 3, array['malware','backup']::text[], true),
('912ae82a-e5f8-52b4-a5a1-2c1604d8b133', '1f6187ce-0423-5375-872c-f8baa84b57a1', 'cq', 'cq', 'bn', 'অনলাইন ক্লাস ও গেমের জন্য সাদিয়া প্রতিদিন প্রায় ৬ ঘণ্টা ল্যাপটপ ব্যবহার করে। সে বিছানায় শুয়ে ল্যাপটপ পেটের উপর রেখে কাজ করে, আর রাতে ঘরের বাতি নিভিয়ে স্ক্রিন পুরো উজ্জ্বল রাখে। ইদানীং তার চোখ জ্বালা করে এবং ঘাড়ে ব্যথা হয়।', null, '[{"part":"a","model":"মানুষের শরীরের সাথে মানানসই করে যন্ত্রপাতি ও কাজের পরিবেশ ডিজাইন ও সাজানোর বিজ্ঞানকে আর্গোনমিক্স বলে।","rubric":[{"points":1,"criterion":"সঠিক সংজ্ঞা"}]},{"part":"b","model":"প্রতি ২০ মিনিট স্ক্রিন ব্যবহারের পর ২০ ফুট (প্রায় ৬ মিটার) দূরের কোনো বস্তুর দিকে ২০ সেকেন্ড তাকাতে হয়।\n\nকাছের স্ক্রিনে একটানা তাকালে চোখের পেশি সংকুচিত থাকে; দূরে তাকালে পেশি শিথিল হয় এবং চোখের ক্লান্তি কমে।","rubric":[{"points":1,"criterion":"নিয়মটি সঠিকভাবে বলেছে"},{"points":1,"criterion":"চোখের পেশি শিথিল হওয়ার কারণ ব্যাখ্যা করেছে"}]},{"part":"c","model":"ঘাড় ব্যথা: শুয়ে পেটের উপর ল্যাপটপ রাখলে স্ক্রিন চোখের অনেক নিচে থাকে, তাই ঘাড় দীর্ঘক্ষণ সামনে বাঁকিয়ে রাখতে হয়। এতে ঘাড়ের পেশিতে চাপ পড়ে।\n\nচোখ জ্বালা: অন্ধকার ঘরে পুরো উজ্জ্বল স্ক্রিন চোখে বেশি চাপ দেয়। তার উপর দিনে ৬ ঘণ্টা বিরতিহীন ব্যবহারে চোখের পলক কম পড়ে, চোখ শুকিয়ে যায়।","rubric":[{"points":1,"criterion":"ভুল ভঙ্গি ও স্ক্রিনের অবস্থানকে ঘাড় ব্যথার কারণ বলেছে"},{"points":1,"criterion":"অন্ধকারে উজ্জ্বল স্ক্রিনকে চোখের কারণ বলেছে"},{"points":1,"criterion":"দীর্ঘ সময় বিরতিহীন ব্যবহারের প্রভাব উল্লেখ করেছে"}]},{"part":"d","model":"১. টেবিল-চেয়ারে বসে কাজ: পিঠ সোজা, পা মেঝেতে। ল্যাপটপ বই বা স্ট্যান্ডের উপর রেখে স্ক্রিনের ওপরের কিনারা চোখের সমান করা, প্রয়োজনে আলাদা কি-বোর্ড। এতে ঘাড় বাঁকাতে হবে না।\n\n২. ঘরে বাতি জ্বালিয়ে রাখা এবং স্ক্রিনের উজ্জ্বলতা ঘরের আলোর কাছাকাছি রাখা; রাতে নাইট মোড। এতে চোখের চাপ কমবে।\n\n৩. ২০-২০-২০ নিয়ম মানা এবং প্রতি ঘণ্টায় উঠে হাঁটা।\n\n৪. গেমের সময় সীমিত করা, যাতে মোট স্ক্রিন সময় কমে।\n\nপরিকল্পনাটি কার্যকর কারণ এটি প্রতিটি সমস্যার মূল কারণ (ভঙ্গি, আলো, বিরতিহীন ব্যবহার) সরাসরি দূর করে, এবং কোনো ব্যয়বহুল যন্ত্র লাগে না।","rubric":[{"points":1,"criterion":"ভঙ্গি ও স্ক্রিনের উচ্চতা ঠিক করার প্রস্তাব"},{"points":1,"criterion":"আলো ও উজ্জ্বলতা ঠিক করার প্রস্তাব"},{"points":1,"criterion":"বিরতি বা স্ক্রিন সময় কমানোর প্রস্তাব"},{"points":1,"criterion":"প্রতিটি প্রস্তাব সমস্যার কারণের সাথে যুক্ত করে যৌক্তিকতা দেখিয়েছে"}]}]'::jsonb, null, '[{"part":"a","marks":1,"prompt":"আর্গোনমিক্স কী?"},{"part":"b","marks":2,"prompt":"২০-২০-২০ নিয়মটি ব্যাখ্যা করো।"},{"part":"c","marks":3,"prompt":"সাদিয়ার চোখ জ্বালা ও ঘাড় ব্যথার কারণ উদ্দীপকের আলোকে ব্যাখ্যা করো।"},{"part":"d","marks":4,"prompt":"সাদিয়ার স্বাস্থ্য সমস্যা দূর করতে একটি কার্যকর পরিকল্পনা প্রস্তাব করো এবং তার যৌক্তিকতা বিশ্লেষণ করো।"}]'::jsonb, 'original', null, null, 3, array['ergonomics','eye-care']::text[], true),
